<?php
function address_api():never{$q=$_GET['q']??'';if(!is_string($q))response_json(['error'=>'INVALID_QUERY','suggestions'=>[]],400);$q=trim($q);rate('address:'.($_SERVER['REMOTE_ADDR']??'local'),120,3600);if(mb_strlen($q)<3||mb_strlen($q)>100||preg_match('/[\x00-\x1f]/',$q))response_json(['error'=>'INVALID_QUERY','suggestions'=>[]],400);try{[$code,$rows]=remote_http('https://openplzapi.org/de/FullTextSearch?searchTerm='.rawurlencode($q).'&page=1&pageSize=8');if($code!==200)throw new RuntimeException();$suggestions=[];foreach(array_slice($rows,0,8) as $r){$street=$r['name']??'';$postcode=$r['postalCode']??'';$city=$r['locality']??'';if(is_string($street)&&is_string($postcode)&&is_string($city)&&preg_match('/^\d{5}$/',$postcode))$suggestions[]=['id'=>hash('sha256',$street.$postcode.$city),'street'=>$street,'postalCode'=>$postcode,'locality'=>$city,'label'=>$street.', '.$postcode.' '.$city];}response_json(['suggestions'=>$suggestions,'source'=>'OpenPLZ']);}catch(Throwable){response_json(['error'=>'DIRECTORY_UNAVAILABLE','suggestions'=>[]],503);}}
